definition.script:
pipeline {
    agent any
    environment {
        PREPARE_CMD = "chmod o-w /workspace/ansible && cd /workspace/ansible"
        BASE_ANSIBLE_PARAMS = "-i ../inventory/general -i /host_dirs/${params.PROJECT_NAME}/inventory"
        ANSIBLE_EXEC = "/root/.local/bin/ansible"
        ANSIBLE_EXEC_PLAYBOOK = "/root/.local/bin/ansible-playbook"
    }
    stages {
        stage('Test connection') {
            steps {
                script {
                      sh """
                        ${env.PREPARE_CMD} && \
                        ${env.ANSIBLE_EXEC} ${env.BASE_ANSIBLE_PARAMS} -m ping deploy
                        """
                }
            }
        }
        stage('Stop containers') {
            when{
                expression { params.STOP_CONTAINERS }
            }
            steps {
                script {
                      sh """
                        ${env.PREPARE_CMD} && \
                        ${env.ANSIBLE_EXEC_PLAYBOOK} ${env.BASE_ANSIBLE_PARAMS} stop-containers.yml
                        """
                }
            }
        }
        stage('Undeploy database') {
            when{
                expression { params.UNDEPLOY_DATABASE }
            }
            steps {
                script {
                      sh """
                        ${env.PREPARE_CMD} && \
                        ${env.ANSIBLE_EXEC_PLAYBOOK} ${env.BASE_ANSIBLE_PARAMS} undeploy-database.yml
                        """
                }
            }
        }
        stage('Full dir remove') {
            when{
                expression { params.FULL_DELETE }
            }
            steps {
                script {
                      sh """
                        ${env.PREPARE_CMD} && \
                        ${env.ANSIBLE_EXEC_PLAYBOOK} ${env.BASE_ANSIBLE_PARAMS} full-dirs-remove.yml
                        """
                }
            }
        }
    }
}
